contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint fundAmount, uint withdrawValue) public payable {
        require(msg.value >= fundAmount, "not enough Ether to fund");
        require(c.depositsCount() == 0, "fresh contract expected");

        // Fund c through its fallback, making the test contract a non-owner sender.
        (bool funded, ) = address(c).call{value: fundAmount}("");
        require(funded, "funding c failed");
        require(address(c).balance >= fundAmount, "c should hold the funded amount");

        // Read observable before-values.
        uint beforeOwnerDeposits = c.depositsCount();
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        bool withdrawReverted;
        try c.withdraw(withdrawValue) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint afterWithdrawCDeposits = c.depositsCount();
        uint afterWithdrawCBalance = address(c).balance;
        uint afterWithdrawThisBalance = address(this).balance;

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        uint afterWithdrawAllCDeposits = c.depositsCount();
        uint afterWithdrawAllCBalance = address(c).balance;
        uint afterWithdrawAllThisBalance = address(this).balance;

        // General non-owner security rule: the owner-only Ether-transferring
        // functions must revert, leave c's balance untouched, and move no Ether
        // to the caller. depositsCount is also unchanged because only fallback
        // increments it and neither failed call can fall through to fallback.
        assert(
            withdrawReverted &&
            withdrawAllReverted &&
            afterWithdrawCBalance == beforeCBalance &&
            afterWithdrawAllCBalance == beforeCBalance &&
            afterWithdrawThisBalance == beforeThisBalance &&
            afterWithdrawAllThisBalance == beforeThisBalance &&
            afterWithdrawCDeposits == beforeOwnerDeposits &&
            afterWithdrawAllCDeposits == beforeOwnerDeposits
        );
    }

    receive() external payable {}
}

